"""Report only results calculated by the metadata rerun."""
from collections import defaultdict
import json
import statistics


def avg(values):
    v=[float(x) for x in values if x!='N/A' and x is not None]
    return statistics.mean(v) if v else 'N/A'


def fmt(x):
    return f'{x:.6f}' if isinstance(x,float) else str(x)


def table(columns,rows):
    safe=lambda x:fmt(x).replace('|','\\|').replace('\n',' ')
    return ['| '+' | '.join(columns)+' |','| '+' | '.join(['---']*len(columns))+' |']+['| '+' | '.join(safe(v) for v in r)+' |' for r in rows]


def build_report(out,coverage,baseline,deltas,masks,annotated,drift,runtime,ablation):
    from evaluate_metadata import read_csv,ROUND1,PHASE1
    primary={r['method']:r for r in annotated if r['variant']=='new_metadata_same19_fit'}
    fullfit={r['method']:r for r in annotated if r['variant']=='new_metadata_full_corpus_fit'}
    winner=max(primary,key=lambda m:primary[m]['mean_tie_expected_ndcg'])
    bestlex=max(['B','C'],key=lambda m:primary[m]['mean_tie_expected_ndcg'])
    draw=abs(primary['D']['mean_tie_expected_ndcg']-primary[bestlex]['mean_tie_expected_ndcg'])<1e-12
    if primary['D']['mean_tie_expected_ndcg']>primary[bestlex]['mean_tie_expected_ndcg']+1e-12:
        verdict='D exceeds both lexical methods on the primary historical-label comparison. This supports retaining it as an experimental comparator, but the narrow single-human judgments and changed evidence do not justify production adoption.'
    elif draw:
        verdict='D ties the best lexical method on the primary historical-label comparison. There is no measured relevance advantage here to offset its additional model/inference requirements.'
    else:
        verdict='D does not outperform the best lexical method on the primary historical-label comparison. This rerun does not justify adding a Sentence Transformer to the final implementation for improved relevance.'
    raw=sum(r['raw_description_present'] for r in coverage);usable=sum(r['usable_in_matched_pools'] for r in coverage)
    menu=sum(r['usable_in_matched_pools'] and r['description_basis'] in ['STRUCTURED_MENU_FACTS','OFFICIAL_MENU_FACTS'] for r in coverage)
    docs=['# TravelSync: A/B/C/D rerun with full-catalogue enriched metadata','',
          '## Result and implementation decision','',
          f'The new compact input contains 3,570 POIs and {raw} nonempty descriptions ({raw/3570:.2%}). After applying the previous two candidate exclusions and quarantining newly flagged conflict metadata, {usable} descriptions are usable in the matched 3,568-row catalogue ({usable/3568:.2%}). Of those usable descriptions, {menu} are menu-fact sentences, not narrative introductions. The source audit and all canonical-feature/string checks passed.','',
          f'Method {winner} has the highest descriptive mean tie-expected NDCG on the original 12 scenarios and original candidate groups, using the same 19-ID lexical fit corpus as Round 1. {verdict}','',
          'The original ratings come from one person completing two sheets, not two independent raters. Revised metadata was not shown to that person for a new evaluation. NDCG therefore measures agreement with fixed historical judgments; it is not a fresh validation of the new evidence or broad-catalogue accuracy. Broader pools receive ranking diagnostics only. No significance claims or production changes are made.','',
          '## Primary matched relevance comparison','',
          'A uses the unchanged production binary scorer. B uses detailed_category + food_type + representative_menu + representative_activity, with the last field mapped to the old activity_type role. C adds description_summary. D uses the same expanded text as C through the exact pinned pretrained multilingual MiniLM encoder. Place names and source/verification/selection/rating fields are never included in scoring text. B/C use unchanged within-token char 2/3-gram raw TF, smoothed IDF, L2 normalization and cosine. Each lexical model is fitted once on the same original 19 POI identities; no query or human grade is fitted.','',
          'Both old and new methods are evaluated against the same 38 annotated pairs, original 12 profile texts/vectors and original per-scenario groups. NDCG uses K=min(3, actual original group size), gain 2^grade−1, logarithmic discount, expected gain over exact score bands (including cutoff crossings), and a separate ID fallback diagnostic. Any insufficient-evidence grade would exclude the entire scenario from NDCG; zero ideal DCG is N/A. Pairwise agreement uses strict human preferences: correct=1, model tie=0.5, reverse=0. Per-sheet values and exclusions remain available. Summary means average the two sheet-specific scenario macro means, not adjudicated/averaged grades.','']
    rows=[['Previous mean tie-expected NDCG']+[primary[m]['old_mean_tie_expected_ndcg'] for m in 'ABCD'],['New mean tie-expected NDCG']+[primary[m]['mean_tie_expected_ndcg'] for m in 'ABCD'],['Change versus previous']+[primary[m]['delta_vs_old_ndcg'] for m in 'ABCD'],['Sheet A new tie-expected NDCG']+[primary[m]['sheet_A_tie_expected_ndcg'] for m in 'ABCD'],['Sheet B new tie-expected NDCG']+[primary[m]['sheet_B_tie_expected_ndcg'] for m in 'ABCD'],['New ID fallback NDCG']+[primary[m]['mean_id_fallback_ndcg'] for m in 'ABCD'],['New scenario-macro pairwise agreement']+[primary[m]['mean_pairwise_agreement'] for m in 'ABCD'],['Evaluated scenarios per sheet']+[primary[m]['evaluated_scenarios_per_sheet'] for m in 'ABCD']]
    docs+=table(['Metric','A','B','C','D'],rows)
    docs+=['','### Fit-corpus and menu-fact controls','',
           'The additional full-corpus fit control keeps exactly the same annotated candidates and grades, but uses B/C IDF from the full 3,568-row new enriched corpus. It isolates fit-corpus sensitivity and is not substituted for the primary matched-19 result. D is corpus-independent; full-fit and same-19 D use the same input text/encoder. A is identical throughout.','']
    docs+=table(['Variant','A NDCG','B NDCG','C NDCG','D NDCG'],[[variant]+[next(r['mean_tie_expected_ndcg'] for r in annotated if r['variant']==variant and r['method']==m) for m in 'ABCD'] for variant in ['new_metadata_same19_fit','new_metadata_full_corpus_fit','new_metadata_no_menu_descriptions_same19_fit']])
    docs+=['','Removing menu-fact descriptions retains B fields and candidate IDs and uses the same fixed C vocabulary/IDF or D encoder. This is an ablation, not a newly trained competitor. Any benefit disappearing here cannot be attributed to rich narrative alone. Annotated grades and corpus hyperparameters were never tuned.','',
           '## Source audit and evidence drift','',
           'The compact model-input file was joined by exact stable IDs to travelsync_poi_metadata_enriched_v1.csv for provenance and to the canonical dataset for identity/features. All 3,570 compact rows, IDs and row order match; every compact cell equals its counterpart in the full companion. Every canonical column string and all ten binary features remain unchanged. Every nonempty ranking field has a field-level source URL/date in the companion provenance JSON. The file name containing “ai” is not taken as evidence that all its text is AI-generated. The supplied report states that introduction excerpts, explicit menu facts and selected prior evidence were used; this experiment audits that supplied provenance rather than independently verifying every source statement.','',
           'Nine new CONFLICT rows are retained in the exact old candidate lists but their new scoring attributes are quarantined. Eight already have null detailed attributes; one still has a tourism-sourced introduction, which is conservatively withheld because its row remains conflicted. Canonical taxonomy can remain available in the matched taxonomy bridge. The original birthplace and Tavolo exclusions are retained even though the new file may contain attributes for them; reintroducing them would change candidate-selection parameters. No feature reclassification occurs.','',
           f'Among the original 19 annotated places, {sum(bool(r["changed_fields"]) for r in drift)} have at least one changed scoring field and {sum(r["description_changed"] for r in drift)} have a changed description string. annotated_evidence_drift.csv preserves old/new descriptions and field differences. The original judgments describe the old evidence. A revised summary dropping a specific attribute does not prove the real place lacks that attribute; neither does an old grade establish the accuracy of a new statement.','']
    basis=read_csv(out/'coverage_by_basis.csv')
    docs+=table(['Description basis','POIs','Nonempty descriptions','Usable descriptions'],[[r['value'],r['pois'],r['raw_descriptions'],r['usable_matched_pool_descriptions']] for r in basis if r['dimension']=='description_basis'])
    docs+=['','## Identical profiles and broader candidate pools','',
           'The previous Experiment 2 membership files are reused verbatim by pool ID: enriched38; nested 100/500/1,000 pools for seeds 11/29/47; and the 3,568-row eligible catalogue. There is no reselection using new scores. Every A/B/C/D comparison within a context uses exactly the same candidate IDs. Smaller pools deliberately anchor the enriched 38 and all feature signatures, so their description prevalence is not representative. The full-catalogue context provides the least selection-dependent coverage diagnostic.','',
           'For a controlled bridge to Experiment 2, original_fields preserves the old four-field structure on the 38 records, and taxonomy_extension preserves category_name + food/menu/activity on the broader corpus. The additional enriched_catalogue context replaces canonical category_name with new detailed_category, enabling full use of the requested compact file. Its comparison with the old taxonomy run changes both supplied data and text representation and is labelled accordingly. Do not attribute that entire difference to descriptions alone. B versus C within the same new context is the description-added comparison.','',
           'The 12 frozen synthetic queries/preference vectors, candidate sizes/seeds, diagnostic K=min(10,n), exact-tie definition, ID fallback, top-K retention/Jaccard, membership-probability overlap and average-tie-rank Spearman match Experiment 2. Constant rank vectors give N/A correlation. Raw score magnitudes are never compared between algorithms. Finite score coverage is not meaningful-query coverage; zero-score ties and positivity are reported separately.','']
    for domain in ['taxonomy_extension','enriched_catalogue']:
        docs+=[f'### Full catalogue: {domain}','']
        r=[r for r in deltas if r['pool_id']=='catalogue3568' and r['domain']==domain]
        docs+=table(['Method','Old mean tie fraction','New mean tie fraction','New positive fraction (text methods)','Old→new top-10 retention','Old→new Spearman'],[[m,avg([x['old_tie_fraction'] for x in r if x['method']==m]),avg([x['new_tie_fraction'] for x in r if x['method']==m]),avg([x['new_positive_score_fraction'] for x in r if x['method']==m]) if m!='A' else 'N/A: survey scale positive',avg([x['topk_id_retention'] for x in r if x['method']==m]),avg([x['spearman_average_tie_ranks'] for x in r if x['method']==m])] for m in 'ABCD'])
    docs+=['','Fewer exact ties, changed top-10 lists or more positive cosine scores are not relevance gains on these unlabelled broader candidate pools. D may separate records even when semantic ordering is wrong. The old→new retention denominator is the old top-K set, while masking below uses each new policy’s unmasked baseline.','',
           '## Missing-description and fallback robustness','',
           'The previous requested rates 0/10/25/50/75% and five seeds 11/29/47/71/101 are retained. Each seed gives nested removal sets among currently usable descriptions, with nearest integer count floor(n×p+0.5); natural missingness remains. The zero case runs once, giving 21 configurations. Mask IDs necessarily differ from the prior experiment because the available description set grew. All algorithms/contexts receive the same new global mask. Smaller pool realized loss can differ from the catalogue rate and is retained per row. No vocabulary, IDF or encoder is refitted after masking.','',
           'C_native and D_native remove only descriptions and score the remaining metadata in the same model space. B_global ignores descriptions. B_backbone_C_ties uses B as the primary sort and C only inside exact B ties; no arithmetic mixture of different scales occurs. C_described_only abstains on missing descriptions while preserving candidate identities and the full coverage denominator. Its tied-pair fraction covers only rankable items.','']
    docs+=table(['Mask %','Policy','Top-10 retention','Worst query/seed retention','Tie-aware membership overlap','Spearman','Rankable fraction'],[[r['requested_percent'],r['policy'],r['mean_topk_id_retention'],r['min_topk_id_retention'],r['mean_membership_probability_overlap'],r['mean_spearman'],r['mean_rankable_fraction']] for r in masks if r['pool_id']=='catalogue3568' and r['domain']=='enriched_catalogue' and r['policy'] in ['C_native','D_native']])
    docs+=['','At 75% removal, full enriched-catalogue fallback comparison:','']
    docs+=table(['Policy','Top-10 retention','Rankable fraction','Mean returned top-K length'],[[r['policy'],r['mean_topk_id_retention'],r['mean_rankable_fraction'],r['mean_topk_returned']] for r in masks if r['pool_id']=='catalogue3568' and r['domain']=='enriched_catalogue' and r['requested_percent']==75])
    docs+=['','The tie-aware overlap is sum(min(p_before,p_after))/min(K,baseline rankable), where p is uniform membership probability within a tied cutoff band; it is not expected overlap of two independent sampled rankings. Identical uninformative all-tied outputs can be perfectly stable. B_global stability is guaranteed because it ignores the removed fields. Random-mask variability is not a confidence interval or a substitute for relevance judgments.','',
           '## Description-basis ablation on the catalogue','',
           'Menu-fact sentences can expose useful explicit menu information absent from representative_menu, but this is structured information in sentence form, not proof that narrative language is necessary. The following fixed-model ablations preserve metadata and candidate pools.','']
    ar=[r for r in ablation if r['pool_id']=='catalogue3568' and r['domain']=='enriched_catalogue']
    docs+=table(['Method','Ablation','Top-10 retention versus all descriptions','Tie fraction','Spearman'],[[m,kind,avg([r['topk_id_retention'] for r in ar if r['method']==m and r['ablation']==kind]),avg([r['exact_tied_pair_fraction'] for r in ar if r['method']==m and r['ablation']==kind]),avg([r['spearman_average_tie_ranks'] for r in ar if r['method']==m and r['ablation']==kind])] for m in ['C','D'] for kind in ['remove_menu_fact_descriptions','remove_all_descriptions']])
    docs+=['','## Cases S01, S07 and S08','']
    ranks=read_csv(out/'annotated_rankings.csv');metrics=read_csv(out/'annotated_per_scenario_metrics.csv')
    original_scores=read_csv(ROUND1/'results/scores_ranks.csv')
    templates=read_csv(ROUND1/'results/annotation_R1.csv')
    profile={r['scenario_id']:r['preference_ko'] for r in templates}
    labels={rid:{(r['scenario_id'],r['place_id']):r['relevance_0_3'] for r in read_csv(PHASE1/f'validated_adapter_{rid}.csv')} for rid in ['R1','R2']}
    for sid in ['S01','S07','S08']:
        docs+=[f'### {sid}','',profile[sid],'']
        candidates=sorted({r['place_id'] for r in ranks if r['scenario_id']==sid})
        rows=[]
        for pid in candidates:
            selected=[r for r in ranks if r['variant']=='new_metadata_same19_fit' and r['scenario_id']==sid and r['place_id']==pid]
            name=selected[0]['place_name']
            rows.append([pid,name,labels['R1'][(sid,pid)],labels['R2'][(sid,pid)]]+[next(r['rank_id_fallback'] for r in selected if r['method']==m) for m in 'ABCD'])
        docs+=table(['POI ID','Candidate','Historical A grade','Historical B grade','A rank','B rank','C rank','D rank'],rows)
        docs+=['','Ranks use ascending ID fallback within exact ties and must not be read as strict preferences when scores tie.','']
        docs+=table(['Method','Old mean tie NDCG','New mean tie NDCG','New macro pairwise'],[[m,avg([r['old_ndcg_tie_expected'] for r in metrics if r['variant']=='new_metadata_same19_fit' and r['scenario_id']==sid and r['method']==m]),avg([r['ndcg_tie_expected'] for r in metrics if r['variant']=='new_metadata_same19_fit' and r['scenario_id']==sid and r['method']==m]),avg([r['pairwise_agreement'] for r in metrics if r['variant']=='new_metadata_same19_fit' and r['scenario_id']==sid and r['method']==m])] for m in 'ABCD'])
        if sid=='S01':
            docs+=['','The new compact file replaces restaurant summaries with menu-fact sentences and updates category granularity. Both historical sheets still prefer the tteokbokki candidate. The ranking/metric table establishes whether D’s earlier reversal persists; no embedding-causality explanation is inferred. The old gamjatang grade-2 note remains a possible rubric interpretation issue, and no grade was changed.','']
        elif sid=='S07':
            docs+=['','The 성지곡 forest summary still explicitly names the requested trees/trail. Category and activity-field changes can alter B and the lexical corpus; consult the evidence-drift CSV before attributing every change to extra narrative. This remains an intentionally constructed original scenario, not an unseen-user test.','']
        else:
            docs+=['','Songdo’s new extractive summary discusses its location/opening history and omits the old explicit sandy-beach/beach-park statement. The historical sheets were shown the old evidence; the revised summary was not re-adjudicated. The old grades are preserved as a historical alignment target, and omitted information is not treated as absence of a beach park.','']
    docs+=['## Runtime and implementation cost','',
           'Existing pinned model files were hash-verified against Round 1, loaded offline and never retrained. Semantic repeat embeddings were byte identical. Sparse lexical storage avoids a large dense document×vocabulary matrix while retaining the exact original TF/IDF equations. A control on the original 19-ID corpus verified identical vocabularies/IDF, numerical scores within 1e-12, and identical historical strict ordering and exact-tie partitions. This backend change is recorded; old dense timings and new sparse timings are not treated as a pure metadata speed comparison.','',
           'The following timings cover warm, preencoded query/document vectors, candidate gathering, scoring and full deterministic sorting. Model loading, fitting, document and query encoding, network, database and UI costs are excluded. Single-query encoding and offline stages are separately recorded in stage_timings.csv. The previous 12 queries × three repeats are retained; these measurements do not establish end-to-end service latency.','']
    rt=[r for r in runtime if r['pool_id']=='catalogue3568' and r['domain']=='enriched_catalogue']
    docs+=table(['Method','Median warm score/sort ms','p95 ms','Measurements'],[[m,statistics.median([r['warm_encoded_score_sort_ms'] for r in rt if r['method']==m]),float(__import__('numpy').percentile([r['warm_encoded_score_sort_ms'] for r in rt if r['method']==m],95)),sum(r['method']==m for r in rt)] for m in 'ABCD'])
    docs+=['','## What the evidence supports','',
           f'1. New metadata has measurable effects on ranking differentiation, query overlap, top-K membership and the fixed historical-label scores. The matched-19 NDCG changes are '+', '.join(f'{m} {primary[m]["delta_vs_old_ndcg"]:+.6f}' for m in 'ABCD')+'. These descriptive changes are not population accuracy estimates.','',
           f'2. C versus B under the same new annotated fit has mean NDCG difference {primary["C"]["mean_tie_expected_ndcg"]-primary["B"]["mean_tie_expected_ndcg"]:+.6f}. Read the per-scenario rows and menu-fact ablation rather than inferring that every description has equal quality or that a minor difference is significant.','',
           '3. '+verdict,'',
           '4. The final implementation decision also needs independent relevance and group-level outcomes. The current evidence contains only 12 synthetic original requests and one annotator’s two sets of grades, some now attached to changed summaries. More description coverage helps feasibility, but does not remove source quality/identity uncertainty or calibrate similarity into member satisfaction.','',
           '5. A controlled offline GFAR experiment can use these frozen models and candidate sets as comparators. Keep per-member utility, minimum utility, group mean/disparity, candidate coverage, returned length and latency visible; calibrate score scales before treating cosine as 1–5 utility. This task makes no production integration or application change.','',
           '## Reproducibility and outputs','',
           'inputs/ holds byte-preserved copies of all three supplied files. source_validation.json records structural/provenance checks; input_coverage.csv and coverage_by_basis.csv retain raw versus usable coverage. config.json and pre_scoring_freeze.json fix profiles, identity lists, text inputs and masks before fitting. manifest.json records source/code hashes, revision and Python/library environment. semantic_metadata.json binds the pinned encoder/files and deterministic repeat. lexical_models.json and scores_*.npz retain fitted vocabulary/IDF and native full-domain score/projection matrices; document order is model_inputs.csv, query order is scenarios.json.','',
           'Main numerical outputs: annotated_method_comparison.csv; annotated_per_scenario_metrics.csv; annotated_rankings.csv; annotated_evidence_drift.csv; method_summary.csv; baseline_ranking_diagnostics.csv; baseline_top10.csv; previous_vs_new_ranking_diagnostics.csv; masking_robustness.csv and masking_summary.csv; description_basis_ablation.csv; runtime_measurements.csv and stage_timings.csv. verification.json records protection of all supplied/canonical/earlier experiment files and exact equality of A scores. Further test/repeat results are attached separately after execution.','',
           'No human labels, source summaries, candidate memberships or model scores were edited to improve results. Old experiments and production files are protected before/after; outputs require a fresh directory. Some source audit rules are automated and not a new human verification of every external statement. No credentials or private repository settings are included.','']
    (out/'metadata_rerun_report.md').write_text('\n'.join(docs)+'\n',encoding='utf-8')
